import DequeModule
import Foundation
@testable import PushInterpreter
import Testing


@Suite @MainActor
struct Stress_Tests {

    // nonisolated so the `.disabled(if:)` trait can read it from the @Test
    // macro's Sendable context under Swift 6 language mode
    nonisolated static let disabledTests = true

    var inty = Interpreter()


    @Test func `set random constants works`() {
        RandomCode.setRandomConstants(in: inty)
        // eight constant-bearing types, ten slots each
        #expect(inty.constants.count == 80)
        #expect((0..<10).allSatisfy { inty.constants[PushInstruction(rawValue: "int\($0)")!] != nil })
    }

    @Test(.disabled(if: Stress_Tests.disabledTests))
    func `random programs run`() async throws {
        let seed: UInt64 = 20_260_714  // fixed & logged so any run reproduces exactly; change to explore new programs
        fuzzRNG = SeededRNG(seed: seed)
        let exploreCases = 200        // random programs generated and profiled in the explore phase
        let batchSize = 20             // explore cases run concurrently per batch; suspects are refined after each batch, so smaller ⇒ sooner feedback
        let programItems = 300         // instruction tokens per random genome (larger ⇒ bigger, more complex programs)
        let windowSize = 100           // interpreter steps per profiling window (the timing/attribution granularity)
        let amplifyAttempts = 6        // mutations per amplified case
        let simplifyAttempts = 40      // chunk-deletions per case
        let simplifyPatience = 50      // stop after this many failed deletions in a row
        let amplifyCapSeconds = 10.0   // wall-clock budget per amplify run (bounds slow candidates)
        let simplifyCapSeconds = 2.0   // a candidate still running past this is "still pathological"
        let slowFloorSeconds = 10.0    // an explore case is collected as a suspect if it runs longer than this
        let slowdownThreshold = 10.0   // ...or if its per-window time grows by more than this factor over the run

        // EXPLORE runs under the real production limits. AMPLIFY runs under
        // relaxed-but-BOUNDED limits: enough headroom for the hill-climb to push a
        // symptom past the default caps.
        //
        // `stepLimit` used to be held down here because provenance was unbounded
        // and a long run reached OOM. `maxCallWeight` now bounds it (an item whose
        // history exceeds the budget forgets it and becomes its own literal), so
        // the step budget is no longer the thing standing between the fuzzer and
        // an out-of-memory crash, and it is raised accordingly. `maxCallWeight` is
        // deliberately left at its production default while the rest are relaxed —
        // if the cap ever fails to hold, this is where it should show up.
        var exploreSettings = InterpreterSettings()
        exploreSettings.stepLimit = 5_000
        var amplifySettings = InterpreterSettings()
        amplifySettings.stepLimit = 100_000
        amplifySettings.maxStackDepth = 20_000
        amplifySettings.maxItemWeight = 2_000_000
        amplifySettings.maxVectorLength = 20_000
        amplifySettings.maxCodePoints = 20_000

        let dir = FileManager.default.temporaryDirectory.appending(path: "push-fuzz")
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let reproEncoder = JSONEncoder()
        let profileEncoder = JSONEncoder()
        profileEncoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        func reproURL(_ id: String) -> URL { dir.appending(path: "\(id).json") }
        func profileURL(_ id: String) -> URL { dir.appending(path: "\(id).profile.json") }

        func requestLike(_ base: EvaluationRequest, id: String, program: [any Item],
                         settings: InterpreterSettings) -> EvaluationRequest {
            EvaluationRequest(
                individuals: [Individual(id: id, program: program, constants: base.individuals[0].constants)],
                trainingCases: [TrainingCase(id: id, inputs: base.trainingCases[0].inputs)],
                pairings: [Pairing(individual: id, trainingCase: id)],
                configuration: RunnerConfiguration(settings: settings)
            )
        }
        func profileOf(_ request: EvaluationRequest, maxSeconds: Double = .infinity) -> RunProfile {
            let ind = request.individuals[0], tc = request.trainingCases[0]
            let interp = buildInterpreter(program: ind.program, constants: ind.constants,
                                          inputs: tc.inputs, settings: request.configuration.settings)
            return profiledRun(id: ind.id, interpreter: interp, windowSize: windowSize, maxSeconds: maxSeconds)
        }
        // Amplify prefers a slower run; when two saturate the time cap, the bigger
        // peak stack (a faster/larger blow-up) breaks the tie.
        func isWorse(_ a: RunProfile, than b: RunProfile) -> Bool {
            if a.totalSeconds > b.totalSeconds + 0.05 { return true }
            if a.totalSeconds >= b.totalSeconds - 0.05 { return a.peakStackItems > b.peakStackItems }
            return false
        }

        var durations: [Double] = []
        var invariantIds: [String] = []
        var sizeLimitHits = 0
        var suspectCount = 0
        var runawayCount = 0                     // programs the runaway guard stopped early
        var runawayExamples: [String] = []       // a few kept for inspection
        var refinedProblems: Set<String> = []   // dedup by dominant culprit: each distinct problem is refined once
        var findings: [String] = []

        // Force-flush so progress is visible in Xcode's console during the long run.
        func log(_ message: String) { print(message); fflush(stdout) }

        // Refine one suspect the moment it appears: amplify it (hill-climb to
        // intensify the symptom), then simplify (delete chunks while the pathology
        // persists), save the minimal example, and return a one-line finding.
        func refine(_ base: EvaluationRequest, _ baseProfile: RunProfile) -> String {
            let caseId = base.individuals[0].id
            let originalSize = base.individuals[0].program.count

            var worstProgram = base.individuals[0].program
            var worstProfile = baseProfile
            for i in 0..<amplifyAttempts {
                let candidateId = "\(caseId)-amp\(i)"
                let candidate = requestLike(base, id: candidateId, program: mutate(program: worstProgram),
                                            settings: amplifySettings)
                try? reproEncoder.encode(candidate).write(to: reproURL(candidateId))
                let p = profileOf(candidate, maxSeconds: amplifyCapSeconds)
                if p.hitInvariant { invariantIds.append(p.id) }
                if !p.hitInvariant && isWorse(p, than: worstProfile) {
                    worstProfile = p; worstProgram = candidate.individuals[0].program
                }
                try? FileManager.default.removeItem(at: reproURL(candidateId))
            }
            let amplifiedSize = worstProgram.count

            var simplest = worstProgram
            var noProgress = 0, j = 0
            while j < simplifyAttempts && simplest.count > 1 && noProgress < simplifyPatience {
                let candidateId = "\(caseId)-simp\(j)"; j += 1
                let candidate = requestLike(base, id: candidateId, program: removeRandomChunk(simplest),
                                            settings: amplifySettings)
                try? reproEncoder.encode(candidate).write(to: reproURL(candidateId))
                let p = profileOf(candidate, maxSeconds: simplifyCapSeconds)
                if p.hitInvariant { invariantIds.append(p.id) }
                if p.capped || p.hitSizeLimit || p.hitInvariant {   // still pathological
                    simplest = candidate.individuals[0].program; noProgress = 0
                } else {
                    noProgress += 1
                }
                try? FileManager.default.removeItem(at: reproURL(candidateId))
            }

            let finalId = "\(caseId)-minimal"
            let minimalRequest = requestLike(base, id: finalId, program: simplest, settings: amplifySettings)
            let minimalProfile = profileOf(minimalRequest, maxSeconds: amplifyCapSeconds)
            try? reproEncoder.encode(minimalRequest).write(to: reproURL(finalId))
            try? profileEncoder.encode(minimalProfile).write(to: profileURL(finalId))
            // Report sizes as top-level count AND leaf count: a program often
            // simplifies to a single code block (count 1) holding many leaves.
            let leaves = programLeafCount(simplest)
            var report = "\(finalId): \(originalSize)→\(amplifiedSize)→\(simplest.count) top-level "
                + "(\(leaves) leaves), "
                + "\(baseProfile.totalSeconds)s→\(worstProfile.totalSeconds)s→\(minimalProfile.totalSeconds)s, "
                + "peak \(minimalProfile.peakStackItems)  [\(minimalProfile.verdict)]"
                + "\n     program [\(finalId)]:\n"
                + renderProgram(simplest)

            // Surface the inputs/constants the program actually reaches (including
            // code-valued inputs that carry the real payload). Without these the
            // program alone can't be understood or reproduced.
            let bindings = base.individuals[0].constants
                .merging(base.trainingCases[0].inputs) { c, _ in c }
            let referenced = referencedClosure(program: simplest, bindings: bindings)
            let bindingLines = renderBindings(referenced, from: bindings)
            if !bindingLines.isEmpty {
                report += "\n     inputs & constants (referenced):\n" + bindingLines.joined(separator: "\n")
            }
            return report
        }

        // ── EXPLORE, refining each distinct problem the moment it appears ─────
        log("fuzzing up to \(exploreCases) random programs of \(programItems) tokens, seed \(seed) (explore stepLimit \(exploreSettings.stepLimit))…")
        // Generate EVERY explore program upfront, in a fixed sequence, so the RNG
        // stream for generation is independent of the (timing-coupled) refinement
        // below. That is what makes a seed reproduce the same programs — and thus
        // the same crashes/pathologies — run to run.
        let allRequests: [EvaluationRequest] = (0..<exploreCases).map { i in
            let temp = Interpreter(); RandomCode.setRandomConstants(in: temp)
            let program = FibonacciGenome.translate(RandomCode.randomProgram(programItems))
            return EvaluationRequest(
                individuals: [Individual(id: "fuzz-\(i)", program: program, constants: temp.constants)],
                trainingCases: [TrainingCase(id: "fuzz-\(i)", inputs: temp.inputs)],
                pairings: [Pairing(individual: "fuzz-\(i)", trainingCase: "fuzz-\(i)")],
                configuration: RunnerConfiguration(settings: exploreSettings)
            )
        }

        var next = 0
        while next < exploreCases {
            let requests = Array(allRequests[next..<min(next + batchSize, exploreCases)])
            next += requests.count
            for r in requests {   // persist before run
                try reproEncoder.encode(r).write(to: reproURL(r.individuals[0].id))
            }

            let results = await withTaskGroup(of: (EvaluationRequest, RunProfile).self) { group in
                for r in requests {
                    group.addTask {
                        let ind = r.individuals[0], tc = r.trainingCases[0]
                        let interp = buildInterpreter(program: ind.program, constants: ind.constants,
                                                      inputs: tc.inputs, settings: r.configuration.settings)
                        return (r, profiledRun(id: ind.id, interpreter: interp, windowSize: windowSize))
                    }
                }
                var out: [(EvaluationRequest, RunProfile)] = []
                for await pair in group { out.append(pair) }
                return out
            }

            // Process in request order (tasks finish out of order) so refinement —
            // which draws from the RNG — happens deterministically for a given seed.
            let profileByID = Dictionary(results.map { ($0.0.individuals[0].id, $0) },
                                         uniquingKeysWith: { first, _ in first })
            for request in requests {
                guard let (r, p) = profileByID[request.individuals[0].id] else { continue }
                durations.append(p.totalSeconds)
                if p.hitSizeLimit { sizeLimitHits += 1 }
                if p.hitInvariant { invariantIds.append(p.id) }

                // The runaway guard already contained these, so they're no longer
                // "slow" suspects to refine — but tally them and keep a few examples,
                // since they're exactly the count-driven loops we care about.
                if p.hitRunaway {
                    runawayCount += 1
                    if runawayExamples.count < 5 {
                        runawayExamples.append("\(p.id): \(p.runawayMessage ?? "")")
                        try? profileEncoder.encode(p).write(to: profileURL(p.id))   // keep for study
                    } else {
                        try? FileManager.default.removeItem(at: reproURL(p.id))
                    }
                    continue
                }

                let suspect = p.hitInvariant || p.hitSizeLimit
                    || p.totalSeconds > slowFloorSeconds || p.slowdownRatio > slowdownThreshold
                guard suspect else {
                    try? FileManager.default.removeItem(at: reproURL(p.id))   // healthy: discard
                    continue
                }
                suspectCount += 1
                try? profileEncoder.encode(p).write(to: profileURL(p.id))     // keep the raw suspect

                // Refine the first example of each distinct problem, immediately.
                let culprit = p.hitInvariant ? "INVARIANT" : p.dominantCulprit
                if refinedProblems.insert(culprit).inserted {
                    log("  ⚠️  new problem in \(p.id) [\(culprit)]: \(p.verdict) — refining…")
                    let finding = refine(r, p)
                    findings.append(finding)
                    log("     ↳ \(finding)\n")   // trailing blank line separates one problem from the next
                }
            }
            log("  …explored \(next)/\(exploreCases): \(suspectCount) suspects, \(refinedProblems.count) distinct problems, \(invariantIds.count) invariants")
        }

        // ── summary ──────────────────────────────────────────────────────────
        let mean = durations.reduce(0, +) / Double(max(durations.count, 1))
        let sd = (durations.map { ($0 - mean) * ($0 - mean) }.reduce(0, +) / Double(max(durations.count, 1))).squareRoot()
        log("""

        ── fuzz summary ──────────────────────────────
        explored         : \(next)
        per-case seconds : mean \(mean), sd \(sd), max \(durations.max() ?? 0)
        size limits hit  : \(sizeLimitHits)
        runaways stopped : \(runawayCount)\(runawayExamples.isEmpty ? "" : "\n" + runawayExamples.map { "  " + $0 }.joined(separator: "\n"))
        suspects         : \(suspectCount)
        distinct problems: \(refinedProblems.count)
        invariants       : \(invariantIds.count) \(invariantIds)
        capture dir      : \(dir.path)
        minimal examples (orig→amp→min items, orig→amp→min seconds):
        \(findings.map { "  " + $0 }.joined(separator: "\n"))
        ──────────────────────────────────────────────
        """)

        #expect(invariantIds.isEmpty)   // regression guard
    }

    // Re-runs a captured reproduction (a `fuzz-*.json` the fuzzer left behind, or
    // an amplified one) with full window profiling, and prints the diagnosis and
    // the slow windows. Point `id` at the case you want to study, then re-enable.
    @Test(.disabled("point at a captured reproduction to study it"))
    func `replay a captured fuzz case`() async throws {
        let id = "fuzz-0"
        let dir = FileManager.default.temporaryDirectory.appending(path: "push-fuzz")
        let request = try JSONDecoder().decode(EvaluationRequest.self, from: Data(contentsOf: dir.appending(path: "\(id).json")))
        let ind = request.individuals[0], tc = request.trainingCases[0]
        let interp = buildInterpreter(program: ind.program, constants: ind.constants, inputs: tc.inputs,
                                      settings: request.configuration.settings)
        let profile = profiledRun(id: id, interpreter: interp, windowSize: 100)

        print("verdict:", profile.verdict)
        print("steps \(profile.totalSteps), \(profile.totalSeconds)s, errors \(profile.errorCount), slowdown \(profile.slowdownRatio)x")
        let typical = profile.totalSeconds / Double(max(profile.windows.count, 1))
        for w in profile.windows where w.seconds > typical * 3 {
            print("  slow window @\(w.firstStep): \(w.seconds)s items=\(w.stackItemsAtEnd) top=\(w.topInstructions)")
        }
    }

